#ifndef SPATIAL_ROW_PRUNING_H
#define SPATIAL_ROW_PRUNING_H

/* Exact divisor-triangular pruning for the buffered spatial row family.
 *
 * If s|Q and 2*H_s-2 >= Q/s, the legal complete s-rows span W_s.  Hence
 * every q-block with s|q and q!=s is generated by blocks at proper divisors
 * of q.  The reductions for different s may be combined because every
 * substitution strictly decreases q.  It is therefore enough to store the
 * divisibility-minimal qualifying s.
 *
 * For an even period Q/s, a surviving anchor block may also be restricted
 * to the Q/s shifts in the reflection-stable set
 *
 *     {u,-u-1 : 0 <= u < Q/(2s)}.
 *
 * This gives exactly Q/(2s) rows in either coordinate-parity sector.  We do
 * not apply this optional shift cap when Q/s is odd, since the programs using
 * this header generally certify one parity and infer the other by reflection.
 */

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

typedef int (*SpatialWindowRadiusFn)(void *context, int q);

typedef struct {
    int q_total;
    int anchor_count;
    int *anchors;
    SpatialWindowRadiusFn radius;
    void *radius_context;
} SpatialRowPruning;

static inline int spatial_int_compare(const void *left, const void *right) {
    int a = *(const int *)left;
    int b = *(const int *)right;
    return (a > b) - (a < b);
}

static inline int spatial_row_pruning_qualifies(
    const SpatialRowPruning *plan, int s) {
    int radius = plan->radius(plan->radius_context, s);
    int period = plan->q_total / s;
    return (int64_t)2 * radius - 2 >= period;
}

static inline void spatial_row_pruning_init(
    SpatialRowPruning *plan, int q_total, SpatialWindowRadiusFn radius,
    void *radius_context) {
    if (q_total <= 0 || radius == NULL) {
        fprintf(stderr, "invalid spatial row-pruning parameters\n");
        exit(EXIT_FAILURE);
    }
    *plan = (SpatialRowPruning){
        .q_total = q_total,
        .anchor_count = 0,
        .anchors = NULL,
        .radius = radius,
        .radius_context = radius_context,
    };

    int candidate_count = 0;
    for (int divisor = 1; divisor <= q_total / divisor; divisor++) {
        if (q_total % divisor != 0)
            continue;
        if (spatial_row_pruning_qualifies(plan, divisor))
            candidate_count++;
        int paired = q_total / divisor;
        if (paired != divisor &&
            spatial_row_pruning_qualifies(plan, paired))
            candidate_count++;
    }
    if (candidate_count == 0)
        return;

    int *candidates = malloc((size_t)candidate_count * sizeof(*candidates));
    if (candidates == NULL) {
        fprintf(stderr, "out of memory allocating row-pruning anchors\n");
        exit(EXIT_FAILURE);
    }
    int position = 0;
    for (int divisor = 1; divisor <= q_total / divisor; divisor++) {
        if (q_total % divisor != 0)
            continue;
        if (spatial_row_pruning_qualifies(plan, divisor))
            candidates[position++] = divisor;
        int paired = q_total / divisor;
        if (paired != divisor &&
            spatial_row_pruning_qualifies(plan, paired))
            candidates[position++] = paired;
    }
    if (position != candidate_count) {
        fprintf(stderr, "internal row-pruning divisor-count mismatch\n");
        exit(EXIT_FAILURE);
    }
    qsort(candidates, (size_t)candidate_count, sizeof(*candidates),
          spatial_int_compare);

    int minimal_count = 0;
    for (int index = 0; index < candidate_count; index++) {
        int s = candidates[index];
        int covered = 0;
        for (int prior = 0; prior < minimal_count; prior++) {
            if (s % candidates[prior] == 0) {
                covered = 1;
                break;
            }
        }
        if (!covered)
            candidates[minimal_count++] = s;
    }
    plan->anchor_count = minimal_count;
    plan->anchors = candidates;
}

static inline void spatial_row_pruning_destroy(SpatialRowPruning *plan) {
    free(plan->anchors);
    plan->anchors = NULL;
    plan->anchor_count = 0;
}

static inline int spatial_row_pruning_is_anchor(
    const SpatialRowPruning *plan, int q) {
    for (int index = 0; index < plan->anchor_count; index++)
        if (plan->anchors[index] == q)
            return 1;
    return 0;
}

static inline int spatial_row_pruning_is_selected(
    const SpatialRowPruning *plan, int q) {
    for (int index = 0; index < plan->anchor_count; index++) {
        int s = plan->anchors[index];
        if (q != s && q % s == 0)
            return 0;
    }
    return 1;
}

/* Number of reflected shift pairs to retain from a q-block. */
static inline int spatial_row_pruning_pair_count(
    const SpatialRowPruning *plan, int q, int radius) {
    int count = radius > 0 ? radius - 1 : 0;
    int period = plan->q_total / q;
    if (spatial_row_pruning_is_anchor(plan, q) && (period & 1) == 0 &&
        count > period / 2)
        count = period / 2;
    return count;
}

/* Number of full-family shifts retained from a q-block. */
static inline int64_t spatial_row_pruning_full_row_count(
    const SpatialRowPruning *plan, int q, int radius) {
    int64_t count = (int64_t)2 * radius - 2;
    if (count < 0)
        count = 0;
    int period = plan->q_total / q;
    if (spatial_row_pruning_is_anchor(plan, q) && (period & 1) == 0 &&
        count > period)
        count = period;
    return count;
}

/* Test membership in the reflection-stable capped shift set. */
static inline int spatial_row_pruning_shift_selected(
    const SpatialRowPruning *plan, int q, int shift) {
    int period = plan->q_total / q;
    if (!spatial_row_pruning_is_anchor(plan, q) || (period & 1) != 0)
        return 1;
    int pair_index = shift >= 0 ? shift : -shift - 1;
    return pair_index < period / 2;
}

static inline void spatial_row_pruning_print(
    FILE *stream, const SpatialRowPruning *plan) {
    fprintf(stream, "pruning_anchors=");
    if (plan->anchor_count == 0) {
        fputs("none", stream);
        return;
    }
    for (int index = 0; index < plan->anchor_count; index++) {
        if (index != 0)
            fputc(',', stream);
        fprintf(stream, "%d", plan->anchors[index]);
    }
}

#endif
